target.css:
:root {
  --ink: #17233b;
  --navy: #203f68;
  --paper: #fffdf7;
  --mist: #eaf0f5;
  --line: #d5dde6;
  --lime: #b7df4b;
  --coral: #f17866;
  --muted: #66748a;
}

* {
  box-sizing: border-box;
}

.bookmobile {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  color: var(--paper);
  background: var(--navy);
}

.kicker {
  margin: 0 0 2px;
  color: var(--lime);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .8px;
}

.route h1 {
  margin: 0;
  font-size: 19px;
  line-height: 1.05;
}

.status {
  margin: 0;
  padding: 4px 7px;
  color: var(--navy);
  background: var(--lime);
  border-radius: 999px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .6px;
}

.stop-time {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 1px 10px;
  align-items: end;
  padding: 7px 16px;
  background: var(--mist);
  border-bottom: 1px solid var(--line);
}

.stop-time span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.stop-time strong {
  font-size: 14px;
}

.stop-time time {
  grid-row: span 2;
  color: var(--navy);
  font-size: 11px;
  font-weight: 800;
}

.manifest {
  padding: 8px 16px 6px;
}

.manifest-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 3px;
}

.manifest-head h2 {
  margin: 0;
  font-size: 12px;
}

.legend {
  display: flex;
  gap: 7px;
  margin: 0;
  color: var(--muted);
  font-size: 9px;
}

.legend span {
  display: flex;
  align-items: center;
  gap: 3px;
}

.legend i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

.dot-lime {
  background: var(--lime);
}

.dot-coral {
  background: var(--coral);
}

.book-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.book {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 35px;
  padding: 4px 0;
}

.book + .book {
  border-top: 1px solid var(--line);
}

.book-icon {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  background: var(--mist);
  border-radius: 7px;
  font-size: 13px;
}

.book-info {
  display: grid;
  gap: 1px;
  flex: 1;
}

.book-info strong {
  font-size: 11px;
}

.book-info small {
  color: var(--muted);
  font-size: 9px;
}

.due {
  display: grid;
  min-width: 31px;
  place-items: center;
  color: var(--navy);
  font-size: 13px;
  font-weight: 900;
  line-height: 1;
}

.due span {
  margin-top: 1px;
  color: var(--muted);
  font-size: 7px;
  font-weight: 700;
  text-transform: uppercase;
}

.due.hold {
  color: var(--coral);
}

.card-footer {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 16px;
  color: var(--paper);
  background: var(--ink);
}

.card-footer p {
  margin: 0;
  font-size: 10px;
  white-space: nowrap;
}

.card-footer strong {
  color: var(--lime);
}

.progress {
  flex: 1;
  height: 5px;
  overflow: hidden;
  background: var(--navy);
  border-radius: 999px;
}

.progress i {
  display: block;
  width: 86%;
  height: 100%;
  background: var(--lime);
  border-radius: inherit;
}

button {
  padding: 4px 7px;
  color: var(--ink);
  background: var(--paper);
  border: 0;
  border-radius: 5px;
  font-size: 9px;
  font-weight: 800;
}

